  difficulty, level_number, icon_slug, image_url, is_active, in_production, translated_from
)
SELECT src.category_id, t.language, t.question_text, t.correct_answer, t.incorrect_answers,
       src.difficulty, src.level_number, src.icon_slug, src.image_url, true, true, src.id
  FROM public.questions src
  CROSS JOIN (VALUES
    ('en', 'Is it true that a goldfish has a three-second memory?', 'Myth', '["Reality","Only young fish","Only one species"]'::jsonb),
    ('de', 'Stimmt es, dass ein Goldfisch ein Gedächtnis von drei Sekunden hat?', 'Mythos', '["Realität","Nur junge Fische","Nur eine Art"]'::jsonb),
    ('es', '¿Es cierto que un pez de colores tiene tres segundos de memoria?', 'Mito', '["Realidad","Solo los peces jóvenes","Solo una especie"]'::jsonb),
    ('fr', 'Est-il vrai qu''un poisson rouge a trois secondes de mémoire ?', 'Mythe', '["Réalité","Seulement les jeunes poissons","Seulement une espèce"]'::jsonb),
    ('it', 'È vero che un pesce rosso ha tre secondi di memoria?', 'Mito', '["Realtà","Solo i pesci giovani","Solo una specie"]'::jsonb),
    ('pt', 'É verdade que um peixinho-dourado tem três segundos de memória?', 'Mito', '["Realidade","Só os peixes jovens","Só uma espécie"]'::jsonb)
  ) AS t(language, question_text, correct_answer, incorrect_answers)
 WHERE src.id = '17ac1daa-b816-416c-af14-ee350b23f23f'::uuid
ON CONFLICT (translated_from, language) DO NOTHING;

