       'medium', 20, true, true
  FROM public.categories c
 WHERE c.category_id = 'portuguese_literature'
   AND NOT EXISTS (
     SELECT 1 FROM public.questions q
      WHERE q.category_id = c.id AND q.language = 'pt'
        AND q.question_text = 'Quem escreveu o romance «Terra Sonâmbula»?'
   );

-- No recount here on purpose. trigger_update_category_levels fires AFTER
-- INSERT FOR EACH ROW on questions and already recomputes total_levels
-- with the thinnest-language rule. A second copy of that arithmetic in a
-- migration is how the recount and the trigger drifted apart once before
-- (see 20260909100000_language_specific_levels.sql).

-- Refuse to commit a run that did not actually reach 17 levels. A source
-- row that has since been deleted would otherwise make the INSERT above a
-- silent no-op reported as success.
DO $$
DECLARE short text;
BEGIN
  SELECT string_agg(format('%s/%s=%s', category_id, lang, n), ', ' ORDER BY category_id, lang)
    INTO short
    FROM (
      SELECT c.category_id, l.lang, count(q.id) AS n
        FROM public.categories c
        CROSS JOIN LATERAL unnest(CASE WHEN c.is_language_specific
                                       THEN ARRAY[c.language]
                                       ELSE ARRAY['ka','en','de','es','fr','it','pt']
                                  END) AS l(lang)
        LEFT JOIN public.questions q
          ON q.category_id = c.id AND q.language = l.lang
         AND q.is_active AND q.in_production
       WHERE c.category_id IN ('spanish_literature', 'portuguese_literature', 'myths_reality', 'anime_manga', 'fun_facts', 'science', 'psychology', 'ecology')
       GROUP BY c.category_id, l.lang
      HAVING count(q.id) < 170
    ) AS gaps;
  IF short IS NOT NULL THEN
    RAISE EXCEPTION 'still short of 170 questions: %', short;
  END IF;

  -- And the number the player is actually shown, which comes from the
  -- trigger rather than from the counts above.
  SELECT string_agg(format('%s=%s', category_id, total_levels), ', ' ORDER BY category_id)
    INTO short
    FROM public.categories
   WHERE category_id IN ('spanish_literature', 'portuguese_literature', 'myths_reality', 'anime_manga', 'fun_facts', 'science', 'psychology', 'ecology')
     AND COALESCE(total_levels, 0) < 17;
  IF short IS NOT NULL THEN
    RAISE EXCEPTION 'questions landed but total_levels did not follow: %', short;
  END IF;
END $$;

COMMIT;
